#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

int main() {
    unsigned char salt[32];
    unsigned char hash[32];

    // Generate a random salt
    if (RAND_bytes(salt, 32) != 1) {
        printf("Failed to generate salt\n");
        return EXIT_FAILURE;
    }

    const char* password = "user_password";
    int iterations = 10000;

    // Derive the key using PBKDF2 HMAC with SHA-256
    if (PKCS5_PBKDF2_HMAC(password, strlen(password),
                          salt, 32,
                          iterations, EVP_sha256(),
                          hash) != 1) {
        printf("Failed to derive key\n");
        return EXIT_FAILURE;
    }

    // Output the results in hexadecimal for verification
    printf("Salt: ");
    for (int i = 0; i < 32; ++i) {
        printf("%02x", salt[i]);
    }
    printf("\nHash: ");
    for (int i = 0; i < 32; ++i) {
        printf("%02x", hash[i]);
    }
    printf("\n");

    return EXIT_SUCCESS;
}
